"""matplotlib.backend_managers — tool manager stubs."""

class ToolManager:
    """Registry of toolbar tools attached to a figure. Each tool is
    keyed by name; toggles maintain mutually-exclusive groups."""

    def __init__(self, figure=None):
        self.figure = figure
        self._tools = {}           # name → tool instance
        self._active_toggle = {}   # group → currently-active tool name
        self._keymaps = {}         # name → [shortcut strings]
        self._observers = {}       # event_name → [(cid, callback)]
        self._cid_counter = 0
        self._cid_to_event = {}

    def add_tool(self, name, tool, *args, **kwargs):
        """Instantiate ``tool`` (a class) with ``self`` as the manager
        and register it under ``name``."""
        if isinstance(tool, type):
            instance = tool(self, name, *args, **kwargs)
        else:
            instance = tool
        self._tools[name] = instance
        return instance

    def remove_tool(self, name):
        self._tools.pop(name, None)
        # Clear from any active toggle slot.
        for group, active_name in list(self._active_toggle.items()):
            if active_name == name:
                del self._active_toggle[group]

    def get_tool(self, name, warn=True):
        tool = self._tools.get(name)
        if tool is None and warn:
            import sys
            sys.__stderr__.write(f'[ToolManager] tool {name!r} not found\n')
        return tool

    def trigger_tool(self, name, sender=None, canvasevent=None, data=None):
        """Activate the named tool. Toggle tools enter the active group;
        regular tools just fire their ``trigger`` method."""
        tool = self.get_tool(name, warn=False)
        if tool is None:
            return
        event = ToolTriggerEvent('tool_trigger_event', sender, tool,
                                   canvasevent=canvasevent, data=data)
        # Toggle handling.
        if getattr(tool, 'toggled', None) is not None:
            group = getattr(tool, 'radio_group', None)
            prev_name = self._active_toggle.get(group) if group else None
            if prev_name == name:
                # Toggling off.
                self._active_toggle.pop(group, None)
                tool.toggled = False
            else:
                if prev_name is not None:
                    prev = self._tools.get(prev_name)
                    if prev is not None:
                        prev.toggled = False
                self._active_toggle[group] = name
                tool.toggled = True
        # Fire any trigger() callback on the tool.
        if hasattr(tool, 'trigger'):
            try: tool.trigger(sender, canvasevent, data)
            except Exception: pass
        # Broadcast to observers.
        self._dispatch('tool_trigger_event', event)

    def toolmanager_connect(self, s, func):
        """Subscribe ``func`` to ToolManager event ``s``."""
        self._cid_counter += 1
        cid = self._cid_counter
        self._observers.setdefault(s, []).append((cid, func))
        self._cid_to_event[cid] = s
        return cid

    def toolmanager_disconnect(self, cid):
        s = self._cid_to_event.pop(cid, None)
        if s is None:
            return
        self._observers[s] = [(c, f) for c, f in self._observers.get(s, [])
                                 if c != cid]

    def _dispatch(self, event_name, event):
        for cid, fn in self._observers.get(event_name, []):
            try: fn(event)
            except Exception: pass


# ─── Added: missing public events from upstream backend_managers.py ─


class ToolEvent:
    """Base event class for ToolManager events. Holds the name of the
    triggering event and the tool involved."""

    def __init__(self, name, sender, tool, data=None):
        self.name = name
        self.sender = sender
        self.tool = tool
        self.data = data


class ToolTriggerEvent(ToolEvent):
    """Event fired when a tool is triggered (e.g. pan/zoom buttons
    clicked). Includes the canvas event that caused the trigger when
    available."""

    def __init__(self, name, sender, tool, canvasevent=None, data=None):
        super().__init__(name, sender, tool, data)
        self.canvasevent = canvasevent


class ToolManagerMessageEvent:
    """Status-bar message broadcast by the ToolManager — e.g. cursor
    coordinates as the mouse moves."""

    def __init__(self, name, sender, message):
        self.name = name
        self.sender = sender
        self.message = message


# ─── Added: ToolManager helpers ─────────────────────────────────────


def _tm_active_toggle(self):
    """Currently-active toggle tools, keyed by radio group."""
    return getattr(self, '_active_toggle', {})

def _tm_canvas(self):  return getattr(self.figure, 'canvas', None) if self.figure else None
def _tm_get_tool_keymap(self, name): return getattr(self, '_keymaps', {}).get(name, [])
def _tm_message_event(self, message, sender=None):
    return ToolManagerMessageEvent('tool_message_event', sender, message)
def _tm_set_figure(self, fig, update_tools=True): self.figure = fig
def _tm_tools(self):  return dict(self._tools)
def _tm_update_keymap(self, name, *keys):
    if not hasattr(self, '_keymaps'): self._keymaps = {}
    self._keymaps[name] = list(keys)

ToolManager.active_toggle    = property(_tm_active_toggle)
ToolManager.canvas           = property(_tm_canvas)
ToolManager.figure           = None
ToolManager.get_tool_keymap  = _tm_get_tool_keymap
ToolManager.message_event    = _tm_message_event
ToolManager.set_figure       = _tm_set_figure
ToolManager.tools            = _tm_tools
ToolManager.update_keymap    = _tm_update_keymap
